-- is_srd = FALSE for ALL 48 (conservative legal posture: 2024 text is redesigned; SRD-5.2 coverage
--   unverified; under-claiming is the safe stance with the rights-holder as prospect). SRD-5.1
--   lineage recorded in design_history_note where applicable. Registry stores NO mechanical text.
-- power_source_axis / role_axis = NULL (demand-driven backfill, deferred). fantasy_flavor_tags = [].
--
-- RE-RUN SAFETY: these are plain INSERTs (not idempotent). Run once on empty tables.
-- To rebuild from scratch, uncomment the two TRUNCATEs below first (destructive — wipes the
-- tables, including any analytical-axis backfill done since seed). Default = do nothing on re-run.
-- TRUNCATE TABLE `dnd-trends-index.game_registry.subclasses`;
-- TRUNCATE TABLE `dnd-trends-index.game_registry.vocabulary_lexicon`;

